initJs:
function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const errorDiv = container.querySelector("#error-message");
  const noResultsDiv = container.querySelector("#no-results");

  // 店舗データを取得してドロップダウンに設定
  async function loadStores() {
    const storeSelect = container.querySelector("#select-store");
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタのインデックス
      if (stores) {
        stores.forEach(store => {
          if (store.有効フラグ) {
            const option = document.createElement("option");
            option.value = store.店舗ID;
            option.textContent = `${store.店舗コード} - ${store.店舗名}`;
            storeSelect.appendChild(option);
          }
        });
      }
    } catch (error) {
      console.error("店舗データの読み込みに失敗しました:", error);
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    noResultsDiv.classList.add("hidden");
  }

  // エラーメッセージ非表示
  function hideError() {
    errorDiv.classList.add("hidden");
  }

  // 在庫状況を判定
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock === 0) return "不足";
    if (currentStock <= safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫状況の色を取得
  function getStatusColor(status) {
    switch (status) {
      case "不足": return "#ff6a00";
      case "過剰": return "#ffa500";
      case "適正": return "#28a745";
      default: return "var(--text)";
    }
  }

  // テーブル再描画関数
  function renderRows(inventoryData) {
    hideError();

    if (!inventoryData || inventoryData.length === 0) {
      tbody.innerHTML = "";
      noResultsDiv.classList.remove("hidden");
      return;
    }

    noResultsDiv.classList.add("hidden");

    tbody.innerHTML = inventoryData.map(item => {
      const status = getStockStatus(item.現在在庫数 || 0, item.安全在庫数 || 0);
      const statusColor = getStatusColor(status);
      const updateDate = item.更新日時 ? new Date(item.更新日時).toLocaleString('ja-JP') : '';

      return `
        <tr data-id="${item.商品ID || ''}">
          <td>${item.商品コード || ''}</td>
          <td>${item.商品名 || ''}</td>
          <td style="text-align: right;">${item.現在在庫数 || 0}</td>
          <td style="text-align: right;">${item.安全在庫数 || 0}</td>
          <td style="color: ${statusColor}; font-weight: bold;">${status}</td>
          <td>${updateDate}</td>
        </tr>
      `;
    }).join("");
  }

  // 在庫データを取得・フィルタリング
  async function searchInventory() {
    const storeId = container.querySelector("#select-store").value;
    const category = container.querySelector("#select-category").value;
    const productName = container.querySelector("#input-product-name").value.trim();
    const productCode = container.querySelector("#input-product-code").value.trim();
    const stockStatus = container.querySelector("#select-stock-status").value;

    // バリデーション
    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    // 商品名の特殊文字チェック
    if (productName && /<script|javascript:|on\w+\s*=|'|"|;|DROP|SELECT|INSERT|UPDATE|DELETE/i.test(productName)) {
      showError("商品名に無効な文字が含まれています");
      return;
    }

    // 商品コードの文字チェック（数値のみ許可）
    if (productCode && !/^\d+$/.test(productCode)) {
      showError("商品コードは数値で入力してください");
      return;
    }

    // 最大文字数チェック
    if (productName && productName.length > 255) {
      showError("商品名は255文字以内で入力してください");
      return;
    }

    if (productCode && productCode.length > 20) {
      showError("商品コードは20桁以内で入力してください");
      return;
    }

    try {
      // 商品データを取得
      const products = await window.aivicApi.list(2); // 商品マスタのインデックス
      if (!products) {
        showError("商品データの取得に失敗しました");
        return;
      }

      // フィルタリング
      let filteredProducts = products.filter(product => {
        if (!product.有効フラグ) return false;

        if (category && !product.商品名?.includes(category)) return false;
        if (productName && !product.商品名?.toLowerCase().includes(productName.toLowerCase())) return false;
        if (productCode && product.商品コード !== productCode) return false;

        return true;
      });

      // 在庫情報を模擬データとして生成（実際のシステムでは在庫テーブルから取得）
      const inventoryData = filteredProducts.map(product => {
        const currentStock = Math.floor(Math.random() * 200);
        const safetyStock = Math.floor(Math.random() * 50) + 10;
        const status = getStockStatus(currentStock, safetyStock);

        return {
          商品ID: product.商品ID,
          商品コード: product.商品コード,
          商品名: product.商品名,
          現在在庫数: currentStock,
          安全在庫数: safetyStock,
          在庫状況: status,
          更新日時: product.更新日時
        };
      });

      // 在庫状況でフィルタリング
      if (stockStatus) {
        filteredProducts = inventoryData.filter(item => item.在庫状況 === stockStatus);
        renderRows(filteredProducts);
      } else {
        renderRows(inventoryData);
      }

    } catch (error) {
      console.error("検索エラー:", error);
      showError("検索中にエラーが発生しました");
    }
  }

  // CSVエクスポート
  function exportCSV() {
    const storeId = container.querySelector("#select-store").value;
    if (!storeId) {
      showError("店舗を選択してからエクスポートしてください");
      return;
    }

    const rows = Array.from(tbody.querySelectorAll("tr"));
    if (rows.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "在庫状況", "最終更新日時"];
    const csvData = [headers.join(",")];

    rows.forEach(row => {
      const cells = Array.from(row.querySelectorAll("td"));
      const rowData = cells.map(cell => {
        let value = cell.textContent.trim();
        if (value.includes(",") || value.includes('"') || value.includes("\n")) {
          value = '"' + value.replace(/"/g, '""') + '"';
        }
        return value;
      });
      csvData.push(rowData.join(","));
    });

    const csvContent = "\uFEFF" + csvData.join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute("download", `inventory_${new Date().toISOString().slice(0, 10)}.csv`);
    link.style.visibility = "hidden";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  // 検索条件クリア
  function clearSearch() {
    container.querySelector("#select-store").value = "";
    container.querySelector("#select-category").value = "";
    container.querySelector("#input-product-name").value = "";
    container.querySelector("#input-product-code").value = "";
    container.querySelector("#select-stock-status").value = "";
    tbody.innerHTML = "";
    hideError();
    noResultsDiv.classList.add("hidden");
  }

  // イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", searchInventory);
  container.querySelector("#btn-clear").addEventListener("click", clearSearch);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 初期化
  loadStores();

  // 初期データ表示（空の状態）
  renderRows([]);
}
